\set ON_ERROR_STOP on
BEGIN;
-- These synthetic signed reports exercise SQL authorization, not Engine math.
-- Cross-language HMAC vector generated by Node crypto over the same UTF8 bytes.
CREATE FUNCTION pg_temp.receipt_assert(ok boolean, label text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; RAISE NOTICE 'PASS: %',label; END; $$;
CREATE FUNCTION pg_temp.receipt_denied(statement text, code text, label text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN
    IF SQLSTATE=code THEN PERFORM pg_temp.receipt_assert(true,label); RETURN; END IF;
    RAISE EXCEPTION 'Unexpected SQLSTATE % for %',SQLSTATE,label;
  END;
  RAISE EXCEPTION 'Unexpected acceptance: %',label;
END; $$;
DO $test$
DECLARE
  actor uuid:='98100000-0000-4000-8000-000000000001';
  student uuid:='98100000-0000-4000-8000-000000000002';
  key uuid:='98200000-0000-4000-8000-000000000001';
  receipt uuid:='98300000-0000-4000-8000-000000000001';
  result jsonb; v uuid; e bigint; fp text; payload text; sig text; before_epoch bigint; report jsonb;
  source jsonb:='{"schemaVersion":5,"kind":"composed","id":"fixture","revision":"1","title":"LOCAL RECEIPT FIXTURE","generation":{"schemaVersion":5,"definitions":[],"constraints":[],"maxAttempts":100,"maxDraws":1000},"variables":[],"elements":[]}';
BEGIN
  PERFORM pg_temp.receipt_assert(encode(extensions.hmac(convert_to('Révision — épreuve','UTF8'),decode(repeat('42',32),'hex'),'sha256'),'hex')='a3c64ff09657e0d2e0dc3e1dac12cb4f61e560f083d2e936d7ff074ecb52131d','Node/PostgreSQL UTF8 HMAC agrees');
  INSERT INTO auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
    SELECT id,'authenticated','authenticated',id::text||'@local.invalid','',now(),'{"provider":"email","providers":["email"]}','{"first_name":"LOCAL FIXTURE","birth_date":"2000-01-01"}',now(),now()
    FROM unnest(ARRAY[actor,student]) id;
  UPDATE public.profiles SET role='admin' WHERE id=actor;
  INSERT INTO novlearn_admin_private.test_signing_keys(id,secret) VALUES(key,decode(repeat('42',32),'hex'));
  PERFORM set_config('request.jwt.claim.sub',actor::text,true);
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'is_anonymous',false)::text,true);
  SET LOCAL ROLE authenticated;
  result:=public.admin_save_exercise_draft(NULL,NULL,NULL,source);
  v:=(result->>'versionId')::uuid; e:=(result->>'exerciseId')::bigint; fp:=result->>'fingerprint';
  PERFORM pg_temp.receipt_assert((SELECT test_epoch=0 FROM public.exercise_versions WHERE id=v),'initial epoch is zero');
  PERFORM pg_temp.receipt_denied('SELECT secret FROM novlearn_admin_private.test_signing_keys','42501','Admin cannot read signing keys');
  PERFORM pg_temp.receipt_denied(format('UPDATE public.exercise_versions SET test_epoch=10 WHERE id=%L',v),'42501','Admin cannot set epoch');
  report:=jsonb_build_object('definitionDigest',repeat('a',64),'engineVersion','0.1.0','passed',true,'complete',true,'seeds',jsonb_build_array(jsonb_build_object('seed',42,'passed',true)));
  payload:=jsonb_build_object('schemaVersion',1,'receiptId',receipt,'keyId',key,'actorId',actor,'versionId',v,'fingerprint',fp,'epoch',0,'issuedAt',floor(extract(epoch from clock_timestamp()))::bigint,
    'engineArchiveSha256','650128cdeb1e798b952a09e91b038d018b9e7947d0a6ee4c247695f899190290','report',report,'cases','[]'::jsonb)::text;
  sig:=encode(extensions.hmac(convert_to(payload,'UTF8'),decode(repeat('42',32),'hex'),'sha256'),'hex');
  PERFORM pg_temp.receipt_denied(format('SELECT public.admin_record_exercise_test(%L,%L)',payload,repeat('0',64)),'42501','fabricated signature is rejected');
  PERFORM pg_temp.receipt_denied(format('SELECT public.admin_record_exercise_test(%L,%L)',replace(payload,'"epoch": 0','"epoch": 1'),sig),'42501','modified signed bytes are rejected');
  RESET ROLE;
  UPDATE novlearn_admin_private.test_signing_keys SET enabled=false WHERE id=key;
  SET LOCAL ROLE authenticated;
  PERFORM pg_temp.receipt_denied(format('SELECT public.admin_record_exercise_test(%L,%L)',payload,sig),'42501','disabled key is rejected');
  RESET ROLE;
  UPDATE novlearn_admin_private.test_signing_keys SET enabled=true WHERE id=key;
  SET LOCAL ROLE authenticated;
  result:=public.admin_record_exercise_test(payload,sig);
  PERFORM pg_temp.receipt_assert(result->'recorded'='true'::jsonb AND result->>'receiptId'=receipt::text,'signed receipt recorded');
  PERFORM pg_temp.receipt_assert((SELECT count(*)=1 AND bool_and(actor_id=actor AND fingerprint=fp AND test_epoch=0) FROM public.admin_exercise_test_runs WHERE id=receipt),'record binds actor revision fingerprint and epoch');
  PERFORM public.admin_record_exercise_test(payload,sig);
  PERFORM pg_temp.receipt_assert((SELECT count(*)=1 FROM public.admin_exercise_test_runs WHERE id=receipt),'same signed receipt is idempotent');
  PERFORM pg_temp.receipt_denied(format('UPDATE public.admin_exercise_test_runs SET passed=false WHERE id=%L',receipt),'42501','direct report rewrite rejected');
  PERFORM pg_temp.receipt_denied(format('DELETE FROM public.admin_exercise_test_runs WHERE id=%L',receipt),'42501','direct report deletion rejected');
  PERFORM pg_temp.receipt_denied(format('INSERT INTO public.admin_exercise_test_runs SELECT * FROM public.admin_exercise_test_runs WHERE id=%L',receipt),'42501','direct report insertion rejected');
  PERFORM set_config('request.jwt.claim.sub',student::text,true);
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',student,'is_anonymous',false,'user_metadata',jsonb_build_object('role','admin'))::text,true);
  PERFORM pg_temp.receipt_assert((SELECT count(*)=0 FROM public.admin_exercise_test_runs),'student cannot read reports');
  PERFORM pg_temp.receipt_denied(format('SELECT public.admin_record_exercise_test(%L,%L)',payload,sig),'42501','student metadata cannot grant signer privileges');
  PERFORM set_config('request.jwt.claim.sub',actor::text,true);
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'is_anonymous',true)::text,true);
  PERFORM pg_temp.receipt_denied(format('SELECT public.admin_record_exercise_test(%L,%L)',payload,sig),'42501','anonymous Admin profile is denied');
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'is_anonymous',false)::text,true);
  result:=public.admin_save_exercise_draft(e,v,fp,source||'{"title":"CHANGED"}');
  PERFORM pg_temp.receipt_assert((SELECT test_epoch=1 FROM public.exercise_versions WHERE id=v),'content edit advances epoch');
  PERFORM pg_temp.receipt_denied(format('SELECT public.admin_record_exercise_test(%L,%L)',payload,sig),'PT409','stale receipt cannot bind changed content');
  result:=public.admin_save_exercise_draft(e,v,result->>'fingerprint',source);
  PERFORM pg_temp.receipt_assert(result->>'fingerprint'=fp AND (SELECT test_epoch=2 FROM public.exercise_versions WHERE id=v),'reverted identical content keeps a new epoch');
  PERFORM pg_temp.receipt_denied(format('SELECT public.admin_record_exercise_test(%L,%L)',payload,sig),'PT409','old receipt cannot survive edit and revert');
  PERFORM pg_temp.receipt_assert((SELECT count(*)=1 FROM public.admin_exercise_test_runs WHERE id=receipt),'old history remains retained');
  RESET ROLE;
END;
$test$;
ROLLBACK;
